function box3(c,x,y,w,h,col,d){ d=d==null?14:d; c.fillStyle=shade(col,.18); c.beginPath(); c.moveTo(x,y); c.lineTo(x+d,y-d*.6); c.lineTo(x+w+d,y-d*.6); c.lineTo(x+w,y); c.fill(); c.fillStyle=shade(col,-.28); c.beginPath(); c.moveTo(x+w,y); c.lineTo(x+w+d,y-d*.6); c.lineTo(x+w+d,y+h-d*.6); c.lineTo(x+w,y+h); c.fill(); const g=c.createLinearGradient(x,y,x,y+h); g.addColorStop(0,col); g.addColorStop(1,shade(col,-.15)); c.fillStyle=g; c.fillRect(x,y,w,h); }
