 library:{w:['#6a3a2a','#4a2418','stripe','rgba(0,0,0,.1)'],f:['#7a4a2a','#4a2a14',1],deco(c,v,t){ shelf(c,v?440:200,60,v?150:180,270,4,v?31:37); }},
