 ship:{w:['#8a6a4a','#5a4028','stripe','rgba(0,0,0,.12)'],f:['#6a4a30','#3a2818',1],deco(c,v,t){ for(const x of v?[340,560]:[250,470]){ c.fillStyle='#c8a040'; c.beginPath(); c.arc(x,40,26,0,TAU); c.fill(); const g=c.createLinearGradient(0,16,0,64); g.addColorStop(0,'#3a6aa8'); g.addColorStop(1,'#1a3a6a'); c.fillStyle=g; c.beginPath(); c.arc(x,40,19,0,TAU); c.fill(); c.fillStyle='rgba(255,255,255,.5)'; c.fillRect(x-16,46+Math.sin(t*2+x)*3,32,2); } }},
