/* 密碼的答案和說明 */
function codeInfo(k,C){ const v=C.v;
  if(C.kind==='clock') return {dials:[10,10,10,10],ans:[Math.floor(v[0]/10),v[0]%10,Math.floor(v[1]/10),v[1]%10],tip:'時鐘是 '+v[0]+' 點 '+String(v[1]).padStart(2,'0')+' 分',how:['＝時鐘指的時間','（四位數，9 點 05 分＝0905）']};
  if(C.kind==='cal') return {dials:[10,10,10,10],ans:[Math.floor(v[0]/10),v[0]%10,Math.floor(v[1]/10),v[1]%10],tip:'日曆圈起來的是 '+v[0]+' 月 '+v[1]+' 日',how:['＝日曆上圈起來的日子','（月月日日，3 月 9 日＝0309）']};
  if(C.kind==='count'){ const use=C.use; return {dials:use.map(()=>10),ans:use.map(col=>(v.find(q=>q[0]===col)||[0,0])[1]),tip:'數一數架子上'+use.map(q=>COLS[q][0]).join('、')+'色的東西：'+use.map(col=>(v.find(q=>q[0]===col)||[0,0])[1]).join('、'),how:['＝架子上 '+use.map(q=>COLS[q][0]).join('、')+' 色東西的數量','（照這個順序）']}; }
  if(C.kind==='books'){ const use=C.use; return {dials:use.map(()=>10),ans:use.map(col=>v.find(q=>q[0]===col)[1]),tip:use.map(q=>COLS[q][0]+'書').join('、')+'上的數字：'+use.map(col=>v.find(q=>q[0]===col)[1]).join('、'),how:['＝'+use.map(q=>COLS[q][0]).join('、')+' 色書背上的數字','（照這個順序）']}; }
  if(C.kind==='color'){ const K=Object.keys(COLS); return {dials:v.map(()=>K),col:1,ans:v.map(q=>K.indexOf(q)),tip:'海報從左到右：'+v.map(q=>COLS[q][0]).join('、'),how:['＝海報上由左到右的顏色']}; }
  if(C.kind==='sym'){ return {dials:v.map(()=>SYM),sym:1,ans:v.map(q=>SYM.indexOf(q)),tip:'黑板上從左到右：'+v.map(q=>SYMN[q]).join(' '),how:['＝黑板上由左到右的符號']}; }
  if(C.kind==='mirror') return {dials:v.map(()=>10),ans:v.slice(),tip:'鏡子上的字是反的，正過來是 '+v.join(''),how:['寫在鏡子上','（字是反過來的喔）']};
  if(C.kind==='dark') return {dials:v.map(()=>10),ans:v.slice(),tip:'用手電筒照牆會出現 '+v.join(' '),how:['寫在牆上，但是看不見','（要用光照才看得到）']};
  if(C.kind==='math') return {dials:v.map(()=>10),ans:v.slice(),tip:'算出來是 '+v.join(''),how:C.lines};
  if(C.kind==='radio') return {dials:v.map(()=>10),ans:v.slice(),tip:'收音機廣播的號碼是 '+v.join(''),how:['＝收音機裡廣播的號碼']}; }
function mkRoom(S){ const codes=S.codes||{},TH=THM[S.th],steps=S.steps,clues=S.clues||[],D=S.door;
  const lockName={}; steps.forEach(s=>{ if(s[0]==='dial') lockName[s[3]]=OBJ[s[2]].n; }); if(D.code) lockName[D.code]='門';
  const panels={},INF={}; for(const k in codes){ INF[k]=codeInfo(k,codes[k]); }
  const gotNote=k=>steps.some((s,i)=>s[4]==='note:'+k);
  steps.forEach((s,i)=>{ if(s[0]==='dial'){ const I=INF[s[3]]; panels['p'+i]={type:'dial',title:OBJ[s[2]].n+'的'+(I.col?'顏色鎖':I.sym?'符號鎖':'密碼鎖'),dials:I.dials,col:I.col,sym:I.sym,ans:I.ans,ok:{f:{['g'+i]:1},add:s[4]&&!/^note:/.test(s[4])?[s[4]]:[],msg:s[5]||'喀！'+OBJ[s[2]].n+'打開了！'+(s[4]?(/^note:/.test(s[4])?'裡面有一張紙條，點它看看。':'裡面有「'+ITEM[s[4]].n+'」。'):'')}}; }
    const g=s[4]; if(g&&/^note:/.test(g)){ const k=g.slice(5); panels['n'+k]={type:'note',on:()=>({['nr'+k]:1}),lines:['寫著字的紙條：',lockName[k]+(codes[k].kind==='color'||codes[k].kind==='sym'?'的鎖':'的密碼')].concat(INF[k].how)}; } });
  clues.forEach(([sl,kind,k])=>{ if(kind==='radio') panels['r'+k]={type:'note',lines:['📻 收音機廣播：','「今天的幸運號碼是…」',codes[k].v.join('、'),'「請記好喔！」']}; });
  if(D.code){ const I=INF[D.code]; panels.door={type:'dial',title:'門的'+(I.col?'顏色鎖':I.sym?'符號鎖':'密碼鎖'),dials:I.dials,col:I.col,sym:I.sym,ans:I.ans,ok:{f:{door:1},msg:'喀！門打開了！點門就能出去。'}}; }
  const powered=F=>S.power==null||F['g'+S.power];
  const objState=(s,i,F)=>({open:!!F['g'+i],lit:!!F['g'+i]});
  function drawView(v){ return (c,F,t)=>{ wall(c,TH.w[0],TH.w[1],TH.w[2],TH.w[3]); floor(c,TH.f[0],TH.f[1],TH.f[2]); if(TH.deco) TH.deco(c,v,t);
    if(v===0){ door(c,590,90,110,240,F.door,S.dc||'#5a4a3a'); if(D.code||D.lock==='power') keypadIcon(c,712,186,powered(F)); else if(D.lock==='card'){ c.fillStyle='#2a2a34'; rr(c,714,186,30,44,4); c.fill(); c.fillStyle=F.door?'#7aff8a':'#ff5a5a'; c.beginPath(); c.arc(729,196,4,0,TAU); c.fill(); c.fillStyle='#555'; c.fillRect(718,208,22,4); } else { c.fillStyle='#c8a040'; c.beginPath(); c.arc(716,214,9,0,TAU); c.fill(); c.fillStyle='#222'; c.beginPath(); c.arc(716,212,3,0,TAU); c.fill(); c.fillRect(715,212,3,8); } }
    clues.forEach(([sl,kind,k])=>{ if(VIEW_OF(sl)!==v) return; const lit=kind==='darkwall'?steps.some((s,i)=>s[0]==='light'&&s[3]===k&&F['g'+i]):1; OBJ[kind==='radio'?'radio':kind].d(c,SLOT[sl],{code:codes[k]&&codes[k].v,lit,open:kind==='radio'&&steps.some((s,i)=>s[0]==='use'&&s[1]===sl&&F['g'+i])},t); });
    steps.forEach((s,i)=>{ if(VIEW_OF(s[1])!==v||clues.some(q=>q[0]===s[1])) return; OBJ[s[2]].d(c,SLOT[s[1]],objState(s,i,F),t); if(s[0]==='find'&&!F['g'+i]&&S.stars<=3) sparkle(c,SLOT[s[1]][0]+SLOT[s[1]][2]*.5,SLOT[s[1]][1]+SLOT[s[1]][3]*.55,t); });
    (S.notes||[]).forEach(([sl,k])=>{ if(VIEW_OF(sl)===v) OBJ.note.d(c,SLOT[sl],{},t); });
  }; }
  function hotView(v){ return F=>{ const L=[];
    steps.forEach((s,i)=>{ if(VIEW_OF(s[1])!==v) return; const [ty,sl,ob,a,give,msg]=s,r=SLOT[sl],nm=OBJ[ob].n,done=!!F['g'+i],nk=give&&/^note:/.test(give)?give.slice(5):null,giveIt=give&&!nk?[give]:[];
      const after=h=>nk?h.open('n'+nk):h.say(nm+'裡已經沒有東西了。');
      if(ty==='find') L.push({r,on:h=>done?after(h):(nk?(h.do({f:{['g'+i]:1},msg:msg||'在'+nm+'找到一張紙條！'}),h.open('n'+nk)):h.do({f:{['g'+i]:1},add:giveIt,msg:msg||'在'+nm+'找到「'+ITEM[give].n+'」！'}))});
      else if(ty==='use') L.push({r,use:{[a]:h=>done?h.say('已經用過了。'):h.do({f:{['g'+i]:1},rm:a==='flash'?[]:[a],add:giveIt,msg:msg||('用「'+ITEM[a].n+'」打開了'+nm+'！'+(give?(nk?'裡面有一張紙條。':'裡面有「'+ITEM[give].n+'」。'):''))})},on:h=>done?after(h):h.say(s[6]||nm+'打不開，好像需要「'+ITEM[a].n+'」。')});
      else if(ty==='dial') L.push({r,on:h=>done?(nk?h.open('n'+nk):h.say(nm+'已經打開了。')):(S.power==null||i<S.power||powered(F))?h.open('p'+i):h.say('沒有電，'+nm+'的鎖不會亮。')});
      else if(ty==='light') L.push({r,use:{flash:h=>h.do({f:{['g'+i]:1},msg:msg||'用手電筒照，'+nm+'上浮現了字！'})},on:h=>done?h.say('牆上寫著：'+codes[a].v.join(' ')):h.say(s[6]||'好像有字，但太暗看不清楚。')});
      else if(ty==='power') L.push({r,use:{fuse:h=>h.do({f:{['g'+i]:1},rm:['fuse'],msg:'裝上保險絲，電來了！燈都亮了。'})},on:h=>done?h.say('配電箱運作中。'):h.say('配電箱少了一顆保險絲。')}); });
    clues.forEach(([sl,kind,k])=>{ if(VIEW_OF(sl)!==v) return; const r=SLOT[sl];
      if(kind==='radio'){ if(!steps.some(s=>s[1]===sl)) L.push({r,on:h=>h.open('r'+k)}); else { const i=steps.findIndex(s=>s[1]===sl); const old=L.find(q=>q.r===r); if(old){ const o0=old.on; old.on=h=>F['g'+i]?h.open('r'+k):o0(h); } } return; }
      if(kind==='darkwall'){ if(!steps.some(s=>s[1]===sl)) L.push({r,on:h=>h.say('牆上好像刻了什麼，太暗看不清楚。')}); return; }
      const say={clock:'時鐘停在 '+(codes[k]?codes[k].v[0]+' 點 '+String(codes[k].v[1]).padStart(2,'0')+' 分':'')+'。',calendar:'日曆上有一天被圈起來了。',shelfc:'架子上擺了各種顏色的東西。',poster:'一張色塊海報。',board:'黑板上畫了幾個符號。',books:'幾本書，書背上寫著數字。',mirror:'鏡子上用口紅寫了字，可是字是反的…'}[kind]||'';
      L.push({r,on:h=>h.say(say)}); });
    (S.notes||[]).forEach(([sl,k])=>{ if(VIEW_OF(sl)===v) L.push({r:SLOT[sl],on:h=>h.open('n'+k)}); });
    if(v===0){ const lr=[704,176,56,70]; if(D.code) L.push({r:lr,on:h=>F.door?h.say('門已經開了！'):!powered(F)?h.say('沒有電，密碼鎖不會亮。'):h.open('door')});
      else if(D.lock==='card') L.push({r:lr,use:{card:h=>h.do({f:{door:1},rm:['card'],msg:'嗶！門打開了！'})},on:h=>h.say('門卡感應器。')});
      else if(D.lock==='power') L.push({r:lr,on:h=>F.door?h.say('門已經開了！'):powered(F)?h.do({f:{door:1},msg:'有電了，門滑開了！'}):h.say('門是電動的，現在沒有電。')});
      else L.push({r:lr,use:{[D.item]:h=>h.do({f:{door:1},rm:[D.item],msg:'喀！門打開了！'})},on:h=>h.say('門鎖著，要用「'+ITEM[D.item].n+'」。')});
      L.push({r:[590,90,110,240],use:D.item?{[D.item]:h=>h.do({f:{door:1},rm:[D.item],msg:'喀！門打開了！'})}:undefined,on:h=>F.door?h.win():h.say('門鎖著。'+(D.code?'旁邊有密碼鎖。':''))}); }
    return L; }; }
  function hint(F){ for(let i=0;i<steps.length;i++){ const [ty,sl,ob,a,give]=steps[i],nm=OBJ[ob].n,side=VIEW_OF(sl)?'另一面牆的':'',nk=give&&/^note:/.test(give)?give.slice(5):null;
      if(!F['g'+i]){ if(ty==='find') return side+nm+'看看，好像藏了東西。'; if(ty==='use') return '選道具「'+ITEM[a].n+'」，再點'+side+nm+'。'; if(ty==='light') return '選手電筒，照照'+side+nm+'。'; if(ty==='power') return '把保險絲裝進'+side+'配電箱。'; if(ty==='dial') return side+nm+'的鎖：'+INF[a].tip+'。'; }
      if(nk&&!F['nr'+nk]) return '看看'+side+nm+'裡的紙條。'; }
    if(!F.door) return D.code?'門的密碼：'+INF[D.code].tip+'。':D.lock==='card'?'把門卡拿到門旁的感應器。':D.lock==='power'?'接上電，門就會打開。':'用「'+ITEM[D.item].n+'」開門。';
    return '點打開的門逃出去！'; }
  return {n:S.n,stars:S.stars,dark:S.power!=null?F=>!powered(F):null,views:[{draw:drawView(0),hot:hotView(0)},{draw:drawView(1),hot:hotView(1)}],panels,hint}; }
